const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const ukGeometry = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'United Kingdom'))
    .geometry();
  const dateStart = '2022-07-19';
  const dateEnd = '2022-07-20';

  // 2. Data Acquisition
  const modisLST = ee.ImageCollection('MODIS/11A1.061/MOD11A1')
    .filterDate(dateStart, dateEnd)
    .select('LST_Day_1km');

  // Check if collection is empty
  const imageCount = modisLST.size().getInfo();
  if (imageCount === 0) {
    console.log('Evidence: No MODIS LST images found for the specified date.');
    console.log('A: No');
    return;
  }
  console.log(`Evidence: Found ${imageCount} MODIS image(s) for 2022-07-19.`);

  // 3. Processing
  // Mosaic the images and scale the LST data. The scale factor is 0.02.
  const tempImage = modisLST.mosaic().multiply(0.02);

  // 4. Calculation
  const maxTempStats = tempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: ukGeometry,
    scale: 1000,
    maxPixels: 1e9
  });

  const maxTempKelvin = maxTempStats.get('LST_Day_1km').getInfo();

  // Check for C2/C3 cases
  if (maxTempKelvin === null) {
      const pixelCountCheck = tempImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: ukGeometry,
        scale: 1000,
        maxPixels: 1e9
      }).get('LST_Day_1km').getInfo();

      if(pixelCountCheck === 0){
        console.log('Evidence: Images exist, but no valid pixels found over the UK.');
        console.log('C2: No Valid Pixels');
        return;
      } else {
        console.log('Evidence: Failed to calculate maximum temperature.');
        console.log('C3: Calculation Failure');
        return;
      }
  }

  // Convert Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  const maxTempFahrenheit = (maxTempKelvin - 273.15) * 1.8 + 32;

  // 5. Validation & Final Answer
  console.log(`Evidence: Maximum recorded surface temperature was ${maxTempFahrenheit.toFixed(2)} °F.`);

  if (maxTempFahrenheit > 100) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
